from scapy.all import rdpcap, DNS, DNSQR
import binascii

def extract_ordered():
    packets = rdpcap('workstation.pcap')
    data = {}
    for pkt in packets:
        if pkt.haslayer(DNS) and pkt.haslayer(DNSQR):
            dns_pkt = pkt.getlayer(DNS)
            if dns_pkt.qr == 0:
                qname = pkt[DNSQR].qname.decode('utf-8', errors='ignore')
                if ".s" in qname and ".cdn-sync.test." in qname:
                    parts = qname.split('.')
                    # qname format: [hex].s000.cdn-sync.test.
                    # parts are: [hex], s000, cdn-sync, test
                    try:
                        hex_str = parts[0]
                        idx_str = parts[1] # e.g., s000
                        idx = int(idx_str[1:])
                        data[idx] = hex_str
                    except:
                        continue

    full_data = b""
    for i in sorted(data.keys()):
        full_data += binascii.unhexlify(data[i])

    print(full_data)

if __name__ == "__main__":
    extract_ordered()
